"""Gives every planned test its own topics, so tests written at the same time do not repeat each other.

  python dev/topic_plan.py          writes dev/topic_plan.json  ({"gt9": {...}, "ac3": {...}, ...})
"""
import json, os

L1 = """booking a table for a large family party at a restaurant|reporting a lost bag at a railway lost-property office|joining a public allotment (vegetable garden) waiting list|hiring a van for a weekend|enrolling a child at a holiday sports camp|arranging a home broadband installation|booking a guided walking holiday|registering with a new doctor's surgery|ordering a made-to-measure bookcase from a carpenter|booking a venue for a wedding reception|arranging pet boarding at a kennels|reporting a fault with a new washing machine|joining a car-sharing scheme|booking a boat trip to see seals|signing up for a first-aid course|arranging a house-sitting service while on holiday|renting a market stall for a craft fair|booking airport parking|enquiring about a part-time job at a garden centre|registering for a city half-marathon|booking driving lessons|arranging the delivery of a second-hand piano|enquiring about volunteering at an animal rescue centre|booking a photographer for a family event|renting a storage unit|booking a campsite pitch for a caravan|arranging a carpet-cleaning visit|joining a choir|booking an eye test and choosing glasses|hiring bicycles for a group ride""".split("|")
L2 = """a tour guide introducing a restored textile mill|a radio item about a new recycling centre's rules|a park ranger briefing visitors to a national park|a talk for new residents of a retirement village|an induction talk for seasonal workers on a fruit farm|a guide describing the layout of a science museum|an announcement about changes at a town's leisure centre|a talk about a city's new tram network|a volunteer organiser explaining a beach clean-up day|a talk about joining a local history society|a guide introducing a castle and its gardens|a manager briefing staff before a music festival|a radio item about a community bakery|a talk for parents about a school's outdoor trips|a guide explaining facilities at a wildlife reserve|a presentation about a neighbourhood tool-lending library|a talk on staying safe when hill walking|an introduction to a city food market tour|a talk about a new community arts centre|a briefing for volunteers at a marathon|a talk about a village's summer fete arrangements|a guide introducing an old lighthouse|a talk about a company's new staff canteen and gym|an introduction to a botanical garden's glasshouses|a talk for new members of a rowing club|a radio item on a repair cafe|a briefing for visitors to a working dairy farm|a talk about a heritage steam railway|an introduction to an open-air swimming pool's season|a talk about a town twinning exchange visit""".split("|")
L3 = """two students planning a survey of student sleeping habits|a student and tutor reviewing a dissertation proposal on urban foxes|two trainee teachers discussing a classroom observation|two students comparing notes on a marketing case study of a failed product|a student getting advice from a tutor on a field trip report about river pollution|two nursing students preparing a presentation on hand hygiene|two architecture students discussing a model of a low-cost house|a student and supervisor discussing interview methods for an oral history project|two business students planning a pop-up cafe project|two students reviewing feedback on a group film project|two geography students analysing data on tourism in a mountain village|a student asking a tutor about choosing a second-year module|two engineering students testing a bridge design|two students preparing a seminar on bilingual children|two students designing a questionnaire about public transport|a student and tutor discussing a literature review on screen time|two students discussing an archaeology dig placement|two students planning a science fair demonstration on solar ovens|two students evaluating a museum exhibition for a course assignment|two students discussing a statistics assignment on house prices|a trainee chef and mentor reviewing a menu-planning assignment|two students planning a debate on zoos|two students discussing a case study of a family business|two students revising an essay plan on the printing press|two students discussing a psychology study of memory and music|two students planning a documentary on a local river|two students comparing internship experiences at a newspaper|a student and tutor discussing a lab report on plant growth under coloured light|two students discussing a sociology project on volunteering|two students preparing a poster on ocean plastics for a conference""".split("|")
L4 = """a lecture on the history of map-making|a lecture on how honeybees communicate|a lecture on the science of bread and fermentation|a lecture on the development of the lighthouse|a lecture on desert plants and how they survive|a lecture on the origins of writing systems|a lecture on noise pollution and health|a lecture on the history of the umbrella|a lecture on how coral reefs form and why they are in danger|a lecture on the psychology of colour in marketing|a lecture on the history of tea drinking|a lecture on bird nests as engineering|a lecture on urban farming|a lecture on the invention of the clock and the idea of time-keeping|a lecture on the Arctic tundra ecosystem|a lecture on the history of spectacles|a lecture on how languages die and are revived|a lecture on the economics of second-hand clothing|a lecture on volcanoes and soil fertility|a lecture on the history of the postal service|a lecture on animal camouflage|a lecture on the design of playgrounds|a lecture on salt in human history|a lecture on how memory champions train|a lecture on mangrove forests|a lecture on the history of the elevator and tall buildings|a lecture on fungi and forest networks|a lecture on the rise of the weekend and leisure time|a lecture on glaciers as climate records|a lecture on the history of soap and hygiene""".split("|")
GT_S1 = """a leisure centre's membership options + a notice about a street market's new opening hours|a community hall hire guide + a library's rules for borrowing e-readers|adverts for four second-hand cars written as short descriptions + a parking permit notice|a doctor's surgery appointment system + a pharmacy's prescription delivery service|a comparison of five mobile phone plans + a notice about a planned water supply interruption|a guide to four local day trips + a hotel's information sheet for guests|a recycling guide for a block of flats + adverts for home services (plumber, gardener, cleaner, electrician)|a holiday cottage rental description + a ferry timetable and ticket rules|a sports club's summer courses for children + a notice about roadworks and diversions|a museum's visitor information + a restaurant's allergy and booking policy|a guide to renting an allotment + adverts for evening classes|a city bike-hire scheme's instructions + a notice from a housing association about repairs""".split("|")
GT_S2 = """a staff handbook section on flexible working + a guide to a company's appraisal process|health and safety rules for a warehouse + how to apply for an internal promotion|a guide to customer complaints handling + a training course catalogue for staff|a company's dress code and identity card policy + advice for chairing meetings|instructions for using a shared company car + a guide to workplace mentoring|rules for working at height on a building site + how to claim overtime|a call centre's quality standards + an introduction to the staff pension scheme|a hotel's housekeeping procedures + advice on giving presentations at work|a guide for new shop assistants on stock handling + data protection rules for office staff|a hospital volunteer handbook + guidance on lone working|a guide to probation periods + fire safety procedures in an office block|a food factory's hygiene rules + advice on writing a CV for an internal transfer""".split("|")
GT_S3 = """the history of the public park|how lighthouse keepers lived and why the job disappeared|the story of the paperback book|the return of wolves to a European region|how the bicycle courier business grew|the history of chocolate from drink to bar|a profile of a village that became energy self-sufficient|the craft of dry-stone walling and its revival|the history of the public library|how a city cleaned up its river|the story of the zip fastener|the rise of community-owned shops and pubs""".split("|")
AC_R = """the origins of the alphabet|how octopuses solve problems|the economics of free public transport|the history of anaesthesia|why some languages have few words for numbers|the science of soil and why it is disappearing|the invention of the sewing machine and its social effects|how cities grew around railways|do animals have a sense of fairness? (argumentative)|the story of rubber|sleep in other animals|is multitasking a myth? (argumentative)|the history of the weather forecast|how plants defend themselves|the case for and against space mining (argumentative)|the lost city and the methods of modern archaeology (lidar)|the biology of ageing in long-lived animals|should museums return objects to their countries of origin? (argumentative)|the history of refrigeration and the food trade|how ants organise without leaders|what makes a good teacher? evidence and opinion (argumentative)|the Silk Road as a network of ideas|the science of taste and smell|the paradox of labour-saving devices (argumentative)|how deep-sea vents changed ideas about life|the rise of the department store|can cities be designed for happiness? (argumentative)|the history of vaccination|how whales evolved from land animals|is handwriting still worth teaching? (argumentative)|the story of concrete|bioluminescence in nature|the limits of economic growth as a measure of progress (argumentative)|the first photographs and how people reacted|how forests recover after fire|does bilingualism make people cleverer? (argumentative)|the history of the calendar|animal migration and the Earth's magnetic field in sea turtles|are zoos justified in the modern world? (argumentative)|the invention of the barcode|the microbiome and human health|why do we procrastinate? (argumentative)|the building of the great cathedrals|how honey is made and why it does not spoil|should we bring extinct species back? (argumentative)|the development of the modern Olympic Games|the physics and biology of bird flight|the attention economy and its critics (argumentative)|the history of aluminium from precious metal to drinks can|how the eye evolved|is nostalgia good for us? (argumentative)|the tulip trade and early financial bubbles|rewilding rivers with beavers|what is intelligence? competing theories (argumentative)""".split("|")
GT_W1 = """a formal letter to a council about a dangerous road crossing|an informal letter inviting a friend to stay and suggesting plans|a semi-formal letter to a manager asking for time off for a course|a formal letter to an airline about damaged luggage|an informal letter thanking a friend for help when you moved house|a semi-formal letter to a landlord about a broken heating system|a formal letter applying to volunteer at a local event|an informal letter to a friend recommending a course you took|a semi-formal letter to a neighbour who is new to the area|a formal letter to a shop about a faulty item bought online|an informal letter apologising for missing a friend's celebration|a semi-formal letter to a gym asking to change your membership""".split("|")
AC_W1 = """line: electricity generation from four sources over 30 years|bar: reasons for visiting a national park, by three age groups|table: average commuting time and cost in five cities|pie: household spending in two different years|line: visitor numbers to three museums over six years|bar: water use per person in five countries, by three sectors|table: literacy and school enrolment in four regions across three decades|pie: how three groups of students travel to university|line: average house prices in three cities over 20 years|bar: number of books borrowed from libraries by format in four years|table: sales of four types of drink in three seasons|pie: sources of a charity's income and how it is spent|line: internet users by age group over 15 years|bar: employment by sector for men and women|table: crop production and land use on farms of three sizes|pie: waste produced by a city in two years by type|line: tourist arrivals in four months compared over three years|bar: time spent on household tasks by age group""".split("|")
W2 = """opinion: children should learn to cook at school|discussion: zoos educate versus zoos are cruel|advantages/disadvantages: living in a big city|problem/solution: traffic congestion in cities|two-part: why do people move abroad for work, and is it positive?|opinion: public transport should be free|discussion: competitive sport in schools|advantages/disadvantages: studying abroad|problem/solution: plastic waste|two-part: why are people reading fewer books, and what can be done?|opinion: advertising aimed at children should be banned|discussion: older people living with family or in care homes|advantages/disadvantages: tourism for small communities|problem/solution: young people's lack of exercise|two-part: why do many people change careers, and is this good?|opinion: governments should spend more on public libraries|discussion: learning online versus in a classroom|advantages/disadvantages: a cashless society|problem/solution: food waste|two-part: why are cities growing so fast, and what problems does this cause?|opinion: everyone should do a year of community service|discussion: news from social media versus newspapers|advantages/disadvantages: a four-day working week|problem/solution: loneliness among older people|two-part: why do people keep pets, and are there drawbacks?|opinion: history is the most important school subject|discussion: preserving old buildings versus building new ones|advantages/disadvantages: children using tablets from an early age|problem/solution: shortage of affordable housing|two-part: why is sleep being neglected, and what are the effects?""".split("|")

plan, n = {}, 0
for i in range(12):   # gt9 .. gt20
    plan[f"gt{9 + i}"] = {"module": "GT", "title": f"General Training Test {9 + i}", "listening": [L1[n], L2[n], L3[n], L4[n]],
                          "reading": ["Section 1: " + GT_S1[i], "Section 2: " + GT_S2[i], "Section 3 (one long text): " + GT_S3[i]],
                          "writing": ["Task 1: " + GT_W1[i], "Task 2 — " + W2[n]]}; n += 1
for i in range(18):   # ac3 .. ac20
    plan[f"ac{3 + i}"] = {"module": "AC", "title": f"Academic Test {3 + i}", "listening": [L1[n], L2[n], L3[n], L4[n]],
                          "reading": [f"Passage {k + 1}: " + AC_R[i * 3 + k] for k in range(3)],
                          "writing": ["Task 1 chart — " + AC_W1[i], "Task 2 — " + W2[n]]}; n += 1
json.dump(plan, open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "topic_plan.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(plan), "tests planned")
